import{_ as t,a8 as e,o as i,c as n,ah as s,K as o}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const g=JSON.parse('{"title":"店小蜜运营：转人工设计与批量测试规范","description":"","frontmatter":{"type":"workflow","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["workflow","店小蜜","淘宝","智能客服","转人工"]},"headers":[],"relativePath":"vault/Memory/Workflows/店小蜜运营与测试集规范.md","filePath":"vault/Memory/Workflows/店小蜜运营与测试集规范.md","lastUpdated":1789374053000}'),d={name:"vault/Memory/Workflows/店小蜜运营与测试集规范.md"};function _(c,a,h,p,b,m){const l=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return i(),n("div",null,[a[0]||(a[0]=s('<h1 id="店小蜜运营-转人工设计与批量测试规范" tabindex="-1">店小蜜运营：转人工设计与批量测试规范 <a class="header-anchor" href="#店小蜜运营-转人工设计与批量测试规范" aria-label="Permalink to “店小蜜运营：转人工设计与批量测试规范”">​</a></h1><p>来源：帮老适智能客服项目实测（2026-07~08）。转人工类知识在平台约束下设计，离开日志无处可查。</p><h2 id="平台硬约束" tabindex="-1">平台硬约束 <a class="header-anchor" href="#平台硬约束" aria-label="Permalink to “平台硬约束”">​</a></h2><ul><li>指定问题策略 ≤50、指定商品策略 ≤30（纯商品维度，不可填关键词）</li><li>关键词格 ≤20 词、相似问题格 ≤500 条</li><li>转人工话术全局仅 1 条</li><li>单条策略只能选「关键词」或「相似问题」其一，不可混行</li><li>多策略命中优先级在平台侧配置，表内无法表达</li></ul><h2 id="转人工设计原则" tabindex="-1">转人工设计原则 <a class="header-anchor" href="#转人工设计原则" aria-label="Permalink to “转人工设计原则”">​</a></h2><ul><li>必 100% 转人工的词（人工/专员/真人）放<strong>关键词模式</strong>保证命中；海量长尾信号放<strong>相似问题模式</strong>。</li><li>医疗信号（中风/偏瘫/骨折/瘫痪/走不了路）<strong>必须转人工且走指定问题而非指定商品</strong>。</li><li>单字裸词（骗/坑/催/烦/反复）必误触发，收紧为具体短语。</li></ul><h2 id="批量测试导入规范-模板-v3" tabindex="-1">批量测试导入规范（模板 V3） <a class="header-anchor" href="#批量测试导入规范-模板-v3" aria-label="Permalink to “批量测试导入规范（模板 V3）”">​</a></h2><ul><li>8 列固定顺序：问题|商品ID|SKU ID|订单状态|售后状态|咨询时间|文档状态|接待模式，仅「问题」必填。</li><li>每次导入 ≤100 条、每日 ≤500 条；咨询时间格式 <code>YYYY-MM-DD HH:MM</code> 零填充去秒。</li></ul><h2 id="测试集管线" tabindex="-1">测试集管线 <a class="header-anchor" href="#测试集管线" aria-label="Permalink to “测试集管线”">​</a></h2><p><code>rebuild_by_session.py</code>（按会话重建+链接绑定商品ID+合并≤3片段+同天≤20分钟护栏）→ <code>dedup_by_intent.py</code>（全局相似聚类 0.84 去重/0.50 合并）→ 按意图拆 ≤100 条文件导入。实测 8859→6485→2775 条。</p><h2 id="测试集必须按会话处理-用户方法论批评-重要" tabindex="-1">测试集必须按会话处理（用户方法论批评，重要） <a class="header-anchor" href="#测试集必须按会话处理-用户方法论批评-重要" aria-label="Permalink to “测试集必须按会话处理（用户方法论批评，重要）”">​</a></h2><p>单消息级清洗是错的：客户单发商品链接消息的 id 是同会话问句的商品上下文；主池去重丢会话ID、不反推商品ID，会把「这个/那款」类问句错判孤儿。<strong>一切清洗以会话ID为单位。</strong></p>',12)),o(l),o(r)])}const k=t(d,[["render",_]]);export{g as __pageData,k as default};
